#!/bin/sh
# Generated by FWShift: the rule tables of one Cisco Meraki MX network, put through the Dashboard API (v1).
# Read the report first: what is not written is listed there. Each put replaces the whole table.
# Usage: MERAKI_API_KEY=... NETWORK_ID=N_... [MERAKI_BASE=https://api.meraki.com/api/v1] [DRY_RUN=1] sh this-file
# DRY_RUN=1 only writes the bodies, and needs no key. The backups (before-*.json) end in the fixed default rule of the
# MX: to put a backup back, remove that last rule (comment "Default rule") from its rules first.
set -eu
OUT="${OUT:-meraki-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
api() {  # api METHOD PATH [BODY-FILE]
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Content-Type: application/json' -H 'Accept: application/json' --data-binary @"$3" "$MERAKI_BASE$2")
    else
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Accept: application/json' "$MERAKI_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/last.json"; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/last.hdr"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/last.json" >&2; return 1 ;;
    esac
  done
}
cat > "$OUT/l3FirewallRules.json" <<'FWSHIFT_EOF'
{
 "rules": [
  {
   "comment": "ipv4rule 4",
   "policy": "allow",
   "protocol": "udp",
   "srcPort": "Any",
   "srcCidr": "192.168.10.0/24",
   "destPort": "514",
   "destCidr": "198.51.100.200/32",
   "syslogEnabled": false
  },
  {
   "comment": "ipv4rule 2",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "198.51.100.0/24",
   "destPort": "102",
   "destCidr": "192.168.10.0/24",
   "syslogEnabled": true
  },
  {
   "comment": "ipv4rule 1",
   "policy": "allow",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "198.51.100.10/32",
   "destPort": "4840",
   "destCidr": "192.168.10.20/32",
   "syslogEnabled": true
  },
  {
   "comment": "ipv4rule 3",
   "policy": "allow",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "198.51.100.40/29,198.51.100.48/31",
   "destPort": "502",
   "destCidr": "192.168.10.30/32",
   "syslogEnabled": false
  },
  {
   "comment": "ipv4rule 6",
   "policy": "allow",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "198.51.100.0/24",
   "destPort": "443",
   "destCidr": "192.168.30.10/32",
   "syslogEnabled": true
  },
  {
   "comment": "ipv4rule 7",
   "policy": "allow",
   "protocol": "tcp",
   "srcPort": "1024-65535",
   "srcCidr": "198.51.100.0/24",
   "destPort": "8000-8100",
   "destCidr": "192.168.30.64/30",
   "syslogEnabled": false
  },
  {
   "comment": "ipv4rule 8",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "192.168.30.0/24",
   "destPort": "Any",
   "destCidr": "192.168.10.0/24",
   "syslogEnabled": true
  },
  {
   "comment": "the source blocks what no rule matches",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   ipv4rule 5: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   ipv4rule 9: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   ipv4rule 11: not converted: source DYNAMIC: the address of the user who activates the rule set, or of the digital input
#   ipv4rule 12: not converted: service ENIP is not in the configuration; references 'ENIP': unsupported or undefined service
#   ipv4rule 13: the source of the rule is in zone ipsecALL, and the MX names no zone: give the networks behind ipsecALL with --zone-network
#   ipv4rule 14: not converted: assigned to the rule set maintenance: it applies only while the set is activated (by a user or a digital input)
#   ipv4rule 15: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   ipv6rule 1: no rule of the MX matches what it matches: host names with IPv6 sources only, or ICMPv6 with IPv4 addresses only (the MX takes host names for IPv4 only)
#   ipv6rule 2: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
